import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.Crpw6aS5.js";const u=JSON.parse('{"title":"苹果公司","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/苹果公司.md","filePath":"03_companies/苹果公司.md"}'),l={name:"03_companies/苹果公司.md"};function o(h,t,i,n,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h2 id="title-苹果公司" tabindex="-1">title: 苹果公司 <a class="header-anchor" href="#title-苹果公司" aria-label="Permalink to &quot;title: 苹果公司&quot;">​</a></h2><h1 id="苹果公司" tabindex="-1">苹果公司 <a class="header-anchor" href="#苹果公司" aria-label="Permalink to &quot;苹果公司&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>信息</th></tr></thead><tbody><tr><td><strong>首次提及</strong></td><td>2016年</td></tr><tr><td><strong>首次建仓</strong></td><td>2016年末</td></tr><tr><td><strong>行业</strong></td><td>科技消费电子</td></tr><tr><td><strong>英文名</strong></td><td>Apple Inc.</td></tr><tr><td><strong>CEO</strong></td><td>蒂姆·库克</td></tr><tr><td><strong>伯克希尔持仓成本</strong></td><td>310.89亿美元（总成本360亿美元，部分出售后）</td></tr></tbody></table><h2 id="持股变化时间线" tabindex="-1">持股变化时间线 <a class="header-anchor" href="#持股变化时间线" aria-label="Permalink to &quot;持股变化时间线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>持股数量</th><th>持股比例</th><th>市值</th><th>关键事件</th></tr></thead><tbody><tr><td>2016年末</td><td>61,242,652股</td><td>1.1%</td><td>70.93亿美元</td><td>首次建仓买入</td></tr><tr><td>2017年末</td><td>166,713,209股</td><td>3.3%</td><td>282.13亿美元</td><td>持续加仓</td></tr><tr><td>2018年7月</td><td>&gt;10亿股（拆股调整后）</td><td>5.2%</td><td>-</td><td>完成建仓，总成本360亿美元</td></tr><tr><td>2018年末</td><td>255,300,329股</td><td>5.4%</td><td>402.71亿美元</td><td>达到5.4%持股</td></tr><tr><td>2019年末</td><td>250,866,566股</td><td>5.7%</td><td>736.67亿美元</td><td>苹果回购使持股比例提升至5.7%</td></tr><tr><td>2020年末</td><td>907,559,761股</td><td>5.4%</td><td>1204.24亿美元</td><td>出售一小部分获利110亿美元，仍因苹果回购维持5.4%持股</td></tr><tr><td>2021年末</td><td>907,559,761股</td><td>5.55%</td><td>1611.55亿美元</td><td>苹果回购使持股比例进一步提升</td></tr><tr><td>2022年</td><td>-</td><td>继续提升</td><td>-</td><td>苹果回购持续增加伯克希尔持股比例（无需额外成本）</td></tr><tr><td>2023年末</td><td>-</td><td>-</td><td>-</td><td>伯克希尔最大单笔市场投资，占GAAP净资产约15%</td></tr><tr><td>2024年</td><td>持续减持</td><td>-</td><td>-</td><td>开始逐步降低持仓</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>苹果公司是全球最大的消费电子公司，主要产品包括：</p><ul><li>iPhone智能手机</li><li>iPad平板电脑</li><li>Mac个人电脑</li><li>Apple Watch智能手表</li><li>服务业务（App Store、Apple Music、iCloud等）</li><li>构建了完整的软硬件生态系统</li></ul><h2 id="与伯克希尔哈撒韦的关系" tabindex="-1">与<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a>的关系 <a class="header-anchor" href="#与伯克希尔哈撒韦的关系" aria-label="Permalink to &quot;与[[伯克希尔哈撒韦]]的关系&quot;">​</a></h2><p>苹果是伯克希尔&quot;四大珍宝&quot;之一（另外三家是保险业务、<a href="/03_companies/BNSF铁路.html">BNSF铁路</a>、<a href="/03_companies/中美能源.html">中美能源</a>），也是巴菲特近年来最成功的投资之一。</p><blockquote><p>&quot;我们第二和第三有价值的资产——目前基本上难分伯仲——是伯克希尔100%拥有的<a href="/03_companies/BNSF铁路.html">BNSF铁路</a>（按货运量计美国最大的铁路公司）以及我们持有的5.4%的<a href="/03_companies/苹果公司.html">苹果公司</a>股权。&quot; —— <a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2020年股东信</p></blockquote><p>投资历程：</p><ul><li>2016年末：伯克希尔开始分批买入苹果股票</li><li>2018年7月：完成建仓，持有略多于10亿股（拆股调整后），总成本360亿美元</li><li>2020年：出售一小部分持仓，获利110亿美元，收回全部初始投资成本后仍持有5.4%股权</li><li>此后：持续享受苹果股票回购带来的被动持股比例提升，无需任何额外成本</li><li>2024年：开始逐步减持</li></ul><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><p>巴菲特将苹果视为<strong>消费品牌企业</strong>而非纯粹的科技公司：</p><ol><li><p><strong>无与伦比的品牌忠诚度与生态锁定</strong>：用户对苹果产品有极高的忠诚度，更换成本极高，形成了宽阔的护城河。用户沉浸在iOS生态系统中，很难转换到其他平台。</p></li><li><p><strong>优秀的资本配置能力</strong>：蒂姆·库克领导下，苹果大规模持续回购股票，这让长期股东的权益不断增值，伯克希尔就是最大受益者之一。</p></li><li><p><strong>持续增长的股息</strong>：苹果持续提高分红，为伯克希尔带来稳定的现金流入。</p></li><li><p><strong>蒂姆·库克的出色管理</strong>：巴菲特多次公开赞扬库克的管理才能。</p></li></ol><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;伯克希尔对苹果的投资清楚地说明了回购的力量。我们于2016年末开始购买苹果股票，到2018年7月初，已持有略多于10亿股苹果股票（经拆股调整后）。当我们在2018年中期完成购买时，伯克希尔一般账户持有苹果5.2%的股权。我们该持仓的成本为360亿美元。自那时以来，我们既享受了定期股息，平均每年约7.75亿美元，又在2020年通过出售一小部分持仓额外获得了110亿美元。尽管进行了上述出售——瞧！——伯克希尔现在持有苹果5.4%的股权。这一增加对我们毫无成本，原因是苹果持续回购其股票，从而大幅减少了其在外流通股数。&quot; —— 2020年股东信</p></blockquote><blockquote><p>&quot;但这还不是全部好消息。因为在这两年半期间我们也回购了伯克希尔股票，你们现在间接拥有的苹果资产和未来收益比2018年7月时多出了10%。这种令人愉悦的动态仍在持续。&quot; —— 2020年股东信</p></blockquote><blockquote><p>&quot;正如性感的梅·韦斯特向我们保证的：&#39;好东西太多可以……太棒了。&#39;&quot; —— 2020年股东信</p></blockquote><blockquote><p>&quot;苹果——按年末市值衡量的第二大巨头——是一种不同类型的持股。在这里，我们的持股比例仅为5.55%，高于一年前的5.39%。这个增幅听起来微不足道。但请考虑，苹果2021年收益的每0.1%都相当于1亿美元。我们没有花费伯克希尔的资金来获得这种增持。苹果的股票回购完成了这项工作。&quot; —— 2021年股东信</p></blockquote><blockquote><p>&quot;重要的是要理解，只有苹果的股息才会计入伯克希尔报告的GAAP收益——去年，苹果向我们支付了7.85亿美元的股息。然而，我们在苹果收益中的&#39;份额&#39;却高达惊人的56亿美元。该公司保留的大部分资金用于回购苹果股票，我们对此表示赞赏。蒂姆·库克，苹果才华横溢的首席执行官，理所当然地将苹果产品的用户视为他的最爱，但他所有其他利益相关者也受益于蒂姆的管理才能。&quot; —— 2021年股东信</p></blockquote><blockquote><p>&quot;2022年，通过伯克希尔股票回购以及我们在苹果和<a href="/03_companies/美国运通.html">美国运通</a>（这两家都是我们重要的投资对象）的类似操作，每股内在价值有了非常微小的增长。在伯克希尔，我们通过回购公司1.2%的流通股，直接增加了你们对我们独特企业集合的权益。在苹果和<a href="/03_companies/美国运通.html">美国运通</a>，回购增加了伯克希尔的持股比例，而我们无需任何成本。&quot; —— 2022年股东信</p></blockquote><blockquote><p>&quot;另一方面，我们持有十几家非常大的、盈利能力极强的知名企业的少量股份，如苹果、<a href="/03_companies/美国运通.html">美国运通</a>、<a href="/03_companies/可口可乐.html">可口可乐</a>和<a href="/03_companies/穆迪.html">穆迪</a>。其中许多公司的净有形净资产要求产生了非常高的回报率。&quot; —— 2024年股东信</p></blockquote><h2 id="财务表现-伯克希尔视角" tabindex="-1">财务表现（伯克希尔视角） <a class="header-anchor" href="#财务表现-伯克希尔视角" aria-label="Permalink to &quot;财务表现（伯克希尔视角）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>金额</th><th>时间</th></tr></thead><tbody><tr><td>累计建仓总成本</td><td>360亿美元</td><td>2016-2018</td></tr><tr><td>2020年部分出售获利</td><td>110亿美元</td><td>2020</td></tr><tr><td>平均年股息收入（2018-2020）</td><td>~7.75亿美元</td><td>每年</td></tr><tr><td>2021年股息收入</td><td>7.85亿美元</td><td>2021</td></tr><tr><td>伯克希尔按比例享有的2021年净利润</td><td>56亿美元</td><td>2021</td></tr><tr><td>2020年末市值</td><td>1204.24亿美元</td><td>2020</td></tr><tr><td>2021年末市值</td><td>1611.55亿美元</td><td>2021</td></tr></tbody></table><p>截至2021年末，伯克希尔持仓盈利超过1300亿美元，是其历史上最成功的投资之一。</p><h2 id="相关人物" tabindex="-1">相关人物 <a class="header-anchor" href="#相关人物" aria-label="Permalink to &quot;相关人物&quot;">​</a></h2><ul><li><a href="/search.html?q=蒂姆·库克">蒂姆·库克</a> - 苹果CEO，巴菲特高度赞赏其管理能力</li><li><a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a> - 主导对苹果的投资</li><li><a href="/04_people/查理·芒格.html">查理·芒格</a> - 支持此项投资</li></ul><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p><a href="/search.html?q=2016年">2016年</a>, <a href="/search.html?q=2017年">2017年</a>, <a href="/search.html?q=2018年">2018年</a>, <a href="/search.html?q=2019年">2019年</a>, <a href="/search.html?q=2020年">2020年</a>, <a href="/search.html?q=2021年">2021年</a>, <a href="/search.html?q=2022年">2022年</a>, <a href="/search.html?q=2023年">2023年</a>, <a href="/search.html?q=2024年">2024年</a></p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a></li><li><a href="/03_companies/美国运通.html">美国运通</a></li><li><a href="/03_companies/可口可乐.html">可口可乐</a></li><li><a href="/03_companies/BNSF铁路.html">BNSF铁路</a></li><li><a href="/03_companies/中美能源.html">中美能源</a></li></ul>',34)])])}const q=a(l,[["render",o]]);export{u as __pageData,q as default};
